 for file in glob.glob('uniprot_*.tsv'):
  with open(file) as f:
   for row in csv.DictReader(f,delimiter='\t'):
    s=row['Sequence']; score,i=max((sum(a==b for a,b in zip(q,s[i:i+len(q)])),i) for i in range(max(1,len(s)-len(q)+1)))
    matches.app

